            {"value": "43 ألفًا", "title": "فرصة وظيفية مستهدفة", "text": "يستهدف التجمع توفير أكثر من 43 ألف فرصة في الأنشطة الصناعية واللوجستية خلال السنوات العشر المقبلة.", "year": "مستهدف مستقبلي", "source": "وكالة الأنباء السعودية", "url": "https://spa.gov.sa/N2212954"},
            {"value": "20 مليار ريال", "title": "استثمارات مستهدفة", "text": "تقدير الاستثمارات المحلية والأجنبية التي يستهدف مشروع التجمع جذبها.", "year": "مستهدف مستقبلي", "source": "وكالة الأنباء السعودية", "url": "https://spa.gov.sa/N2212954"},
